"""Scan every release file, including this scanner, with the shared release rules."""
from pathlib import Path
import json
import re
import sys
PATTERNS = json.loads(bytes.fromhex("").decode())
RX = re.compile("|".join(PATTERNS), re.I)
def scan(root):
    failures = []
    for path in sorted(root.rglob("*")):
        if path.is_file() and ".git" not in path.relative_to(root).parts:
            text = path.read_bytes().decode("utf-8", "replace")
            if RX.search(path.relative_to(root).as_posix()) or RX.search(text):
                failures.append(str(path.relative_to(root)))
    return failures
if __name__ == "__main__":
    bad = scan(Path(__file__).resolve().parents[2])
    print("PUBLIC SCAN FAILED: " + ", ".join(bad) if bad else "PUBLIC SCAN PASSED: every release file")
    sys.exit(bool(bad))
